let curChaebolIdx = 0;
let chaebolTimer = null;
let chaebolProgressTimer = null;
let chaebolPaused = false;
let chaebolProgressPercent = 0;

function renderChaebolReport(idx) {
  const r = chaebolReportsData[idx];
  const area = document.getElementById('chaebolReportContentArea');
  if (!area) return;
  
  area.style.opacity = '0';
  setTimeout(() => {
    document.getElementById('chaebolReportBadge').innerText = r.badge;
    document.getElementById('chaebolReportCategory').innerText = r.category;
    document.getElementById('chaebolReportTitle').innerText = r.title;
    document.getElementById('chaebolReportSummary').innerText = r.summary;
    
    // metrics
    const mWrap = document.getElementById('chaebolReportMetrics');
    if (mWrap) {
      mWrap.innerHTML = r.metrics.map(m => `
        <div style="background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.06); padding: 8px 12px; border-radius: 8px;">
          <div style="font-size: 11px; color: #86868B;">${m.label}</div>
          <div style="font-size: 13px; font-weight: 800; color: #38BDF8;">${m.val}</div>
        </div>
      `).join('');
    }

    // tags
    const tWrap = document.getElementById('chaebolReportTags');
    if (tWrap) {
      tWrap.innerHTML = r.tags.map(t => `
        <span style="font-size: 11px; color: #9CA3AF; background: rgba(255,255,255,0.04); padding: 2px 7px; border-radius: 4px;">${t}</span>
      `).join('');
    }

    area.style.opacity = '1';
  }, 150);
}

function startChaebolAutoRotation() {
  stopChaebolAutoRotation();
  chaebolProgressPercent = 0;
  
  chaebolProgressTimer = setInterval(() => {
    if (!chaebolPaused) {
      chaebolProgressPercent += 1.25; // 8 seconds (100 / 80)
      const bar = document.getElementById('chaebolProgressFill');
      if (bar) bar.style.width = Math.min(chaebolProgressPercent, 100) + '%';
      
      if (chaebolProgressPercent >= 100) {
        chaebolProgressPercent = 0;
        curChaebolIdx = (curChaebolIdx + 1) % chaebolReportsData.length;
        renderChaebolReport(curChaebolIdx);
      }
    }
  }, 100);
}

function stopChaebolAutoRotation() {
  if (chaebolProgressTimer) clearInterval(chaebolProgressTimer);
}

function nextChaebolReport() {
  chaebolProgressPercent = 0;
  curChaebolIdx = (curChaebolIdx + 1) % chaebolReportsData.length;
  renderChaebolReport(curChaebolIdx);
}

function prevChaebolReport() {
  chaebolProgressPercent = 0;
  curChaebolIdx = (curChaebolIdx - 1 + chaebolReportsData.length) % chaebolReportsData.length;
  renderChaebolReport(curChaebolIdx);
}

function randomChaebolReport() {
  chaebolProgressPercent = 0;
  let newIdx = Math.floor(Math.random() * chaebolReportsData.length);
  if (newIdx === curChaebolIdx) newIdx = (newIdx + 1) % chaebolReportsData.length;
  curChaebolIdx = newIdx;
  renderChaebolReport(curChaebolIdx);
}

function toggleChaebolPause() {
  chaebolPaused = !chaebolPaused;
  const btn = document.getElementById('btnChaebolPause');
  if (btn) btn.innerText = chaebolPaused ? "▶ 재생" : "⏸ 일시정지";
}

function switchChaebolTab(tabName, btn) {
  document.querySelectorAll('.chaebol-tab-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  
  const panes = ['big4', 'big5', 'big31', 'failed', 'books', 'videos'];
  panes.forEach(p => {
    const el = document.getElementById('chaebol-pane-' + p);
    if (el) el.style.display = (p === tabName) ? 'block' : 'none';
  });

  if (tabName === 'books') renderChaebolBooks();
  if (tabName === 'videos') renderChaebolVideos();
}

