function renderChaebolVideos() {
  const grid = document.getElementById('chaebolVideosGrid');
  if (!grid || grid.children.length > 0) return;
  grid.innerHTML = chaebolVideosData.map(v => `
    <div class="chaebol-group-card" style="cursor: pointer;" onclick="playChaebolVideo('${v.id}', '${v.title.replace(/'/g, "\'")}')">
      <div>
        <div style="font-size: 11px; font-weight: 800; color: #38BDF8; margin-bottom: 4px;">${v.src}</div>
        <h4 style="font-size: 1.05rem; font-weight: 800; color: #FFFFFF; margin-bottom: 6px;">${v.title}</h4>
        <p style="font-size: 12px; color: #A1A1A6; line-height: 1.5; margin-bottom: 12px;">${v.desc}</p>
      </div>
      <div style="border-top: 1px solid rgba(255,255,255,0.06); padding-top: 8px; display: flex; justify-content: space-between; align-items: center;">
        <span style="font-size: 11px; color: #10B981;">▶ 플레이어에서 재생</span>
        <span style="font-size: 12px;">📺</span>
      </div>
    </div>
  `).join('');
}

function playChaebolVideo(id, title) {
  const iframe = document.getElementById('chaebolMainIframe');
  const tEl = document.getElementById('chaebolVideoPlayerTitle');
  if (iframe) iframe.src = 'https://www.youtube.com/embed/' + id + '?autoplay=1';
  if (tEl) tEl.innerText = '📺 ' + title;
  const pane = document.getElementById('chaebol-pane-videos');
  if (pane) pane.scrollIntoView({ behavior: 'smooth' });
}

function openChaebolReportModal() {
  const r = chaebolReportsData[curChaebolIdx];
  document.getElementById('modalChaebolBadge').innerText = r.badge + " • " + r.category;
  document.getElementById('modalChaebolTitle').innerText = r.title;
  document.getElementById('modalChaebolBody').innerText = r.body;
  document.getElementById('chaebolReportModal').style.display = 'flex';
}

function closeChaebolReportModal() {
  document.getElementById('chaebolReportModal').style.display = 'none';
}

// Auto start on page load
document.addEventListener('DOMContentLoaded', function() {
  renderChaebolReport(0);
  startChaebolAutoRotation();
});

