let currentDebtPirCat = 'debt'; // 'debt' | 'pir' | 'buffett' | 'ext'
let currentDebtPirSubType = 'debt_hh'; // 'debt_hh' | 'debt_gov' | 'debt_corp' | 'debt_private' | 'debt_total' | 'pir_national' | 'pir_cities' | 'buffett' | 'ext_st' | 'ext_ca'
let currentDebtPirRange = 'all'; // 'all' | '20y' | '10y' | '5y'
let currentDebtSelectedCountries = ['KR', 'US', 'JP', 'OECD'];
let currentDebtCityKey = 'KR_SEOUL';

function setDebtPirCategory(cat) {
  currentDebtPirCat = cat;
  document.querySelectorAll('.debt-cat-btn').forEach(b => b.classList.remove('active'));
  const targetBtn = document.getElementById('btnDebtCat_' + cat);
  if (targetBtn) targetBtn.classList.add('active');

  // Set default sub-type for category
  if (cat === 'debt') currentDebtPirSubType = 'debt_hh';
  else if (cat === 'pir') currentDebtPirSubType = 'pir_national';
  else if (cat === 'buffett') currentDebtPirSubType = 'buffett';
  else if (cat === 'ext') currentDebtPirSubType = 'ext_st';

  renderDebtPirSubTypes();
  renderDebtPirCountryChips();
  renderDebtPirChart();
  renderDebtPirTable();
}

function setDebtPirSubType(subType) {
  currentDebtPirSubType = subType;
  document.querySelectorAll('.debt-sub-btn').forEach(b => b.classList.remove('active'));
  const targetBtn = document.getElementById('btnDebtSub_' + subType);
  if (targetBtn) targetBtn.classList.add('active');

  // Update unit badge
  const unitBadge = document.getElementById('debtPirMetricUnitBadge');
  if (unitBadge) {
    if (subType.includes('pir')) unitBadge.textContent = '단위: 소득 대비 배수 (배, Multiple)';
    else if (subType === 'ext_st') unitBadge.textContent = '단위: 외환보유액 대비 비율 (%)';
    else unitBadge.textContent = '단위: GDP 대비 % (% of GDP)';
  }

  renderDebtPirChart();
  renderDebtPirTable();
}

function renderDebtPirSubTypes() {
  const container = document.getElementById('debtPirSubTypePills');
  if (!container) return;
  container.innerHTML = '';

  let pills = [];
  if (currentDebtPirCat === 'debt') {
    pills = [
      { id: 'debt_hh', label: '🏡 가계부채 (Household)' },
      { id: 'debt_gov', label: '🏛️ 정부부채 (Govt D2)' },
      { id: 'debt_corp', label: '🏭 비금융 기업부채 (Corporate)' },
      { id: 'debt_private', label: '📊 민간신용 총합 (가계+기업)' },
      { id: 'debt_total', label: '📦 3대 부채 총합 (Total)' }
    ];
  } else if (currentDebtPirCat === 'pir') {
    pills = [
      { id: 'pir_national', label: '🏙️ 국가별 전국 PIR (소득대비 주택가격)' },
      { id: 'pir_cities', label: '🇰🇷 서울 vs 뉴욕·런던·도쿄 대도시 PIR' }
    ];
  } else if (currentDebtPirCat === 'buffett') {
    pills = [
      { id: 'buffett', label: '📈 버핏 지수 (GDP 대비 상장주식 시가총액 %)' }
    ];
  } else if (currentDebtPirCat === 'ext') {
    pills = [
      { id: 'ext_st', label: '🛡️ 외환보유액 대비 단기외채 비율 (외환위기 나침반)' },
      { id: 'ext_ca', label: '⚖️ 경상수지 / GDP 비율 (%)' }
    ];
  }

  pills.forEach(p => {
    const btn = document.createElement('button');
    btn.className = 'debt-sub-btn' + (p.id === currentDebtPirSubType ? ' active' : '');
    btn.id = 'btnDebtSub_' + p.id;
    btn.textContent = p.label;
    btn.onclick = () => setDebtPirSubType(p.id);
    container.appendChild(btn);
  });
}

function toggleDebtPirCountry(code) {
  if (currentDebtSelectedCountries.includes(code)) {
    if (currentDebtSelectedCountries.length <= 1) {
      alert('최소 1개 이상의 국가를 선택해야 합니다.');
      return;
    }
    currentDebtSelectedCountries = currentDebtSelectedCountries.filter(c => c !== code);
  } else {
    currentDebtSelectedCountries.push(code);
  }
  renderDebtPirCountryChips();
  renderDebtPirChart();
  renderDebtPirTable();
}

function setDebtPirPreset(preset) {
  if (preset === 'kr_us_jp_oecd') currentDebtSelectedCountries = ['KR', 'US', 'JP', 'OECD'];
  else if (preset === 'g4') currentDebtSelectedCountries = ['KR', 'US', 'CN', 'JP'];
  else if (preset === 'europe') currentDebtSelectedCountries = ['DE', 'GB', 'FR', 'OECD'];
  else if (preset === 'anglo') currentDebtSelectedCountries = ['US', 'GB', 'CA', 'AU'];
  else if (preset === 'all') currentDebtSelectedCountries = ['KR', 'US', 'JP', 'CN', 'DE', 'GB', 'FR', 'CA', 'AU', 'OECD'];

  renderDebtPirCountryChips();
  renderDebtPirChart();
  renderDebtPirTable();
}

function setDebtPirRange(range) {
  currentDebtPirRange = range;
  ['all', '20y', '10y', '5y'].forEach(r => {
    const b = document.getElementById('btnDebtRange_' + r);
    if (b) {
      if (r === range) b.classList.add('active');
      else b.classList.remove('active');
    }
  });
  renderDebtPirChart();
  renderDebtPirTable();
}

function renderDebtPirCountryChips() {
  const container = document.getElementById('debtPirCountryChips');
  if (!container) return;
  container.innerHTML = '';

  const countryKeys = ['KR', 'US', 'JP', 'CN', 'DE', 'GB', 'FR', 'CA', 'AU', 'OECD'];
  countryKeys.forEach(code => {
    const info = MASTER_DEBT_PIR_DATA.countries[code];
    if (!info) return;
    const isAct = currentDebtSelectedCountries.includes(code);
    const chip = document.createElement('button');
    chip.className = 'country-chip-btn' + (isAct ? ' active' : '');
    chip.style.setProperty('--country-color', info.color);
    chip.innerHTML = `<span>${info.flag}</span> <span>${info.name}</span>`;
    chip.onclick = () => toggleDebtPirCountry(code);
    container.appendChild(chip);
  });
}

function getActiveDebtDataset() {
  if (currentDebtPirSubType === 'debt_hh') return { data: MASTER_DEBT_PIR_DATA.debt_hh, title: '주요국 GDP 대비 가계부채비율 (BIS 기준)', unit: '%' };
  if (currentDebtPirSubType === 'debt_gov') return { data: MASTER_DEBT_PIR_DATA.debt_gov, title: '주요국 GDP 대비 정부부채비율 (IMF·OECD D2 기준)', unit: '%' };
  if (currentDebtPirSubType === 'debt_corp') return { data: MASTER_DEBT_PIR_DATA.debt_corp, title: '주요국 GDP 대비 비금융 기업부채비율 (BIS 기준)', unit: '%' };
  if (currentDebtPirSubType === 'debt_private') return { data: MASTER_DEBT_PIR_DATA.debt_private, title: '주요국 GDP 대비 민간신용 총합 (가계+기업부채)', unit: '%' };
  if (currentDebtPirSubType === 'debt_total') return { data: MASTER_DEBT_PIR_DATA.debt_total, title: '주요국 GDP 대비 3대 부채 총합 (정부+가계+기업)', unit: '%' };
  if (currentDebtPirSubType === 'pir_national') return { data: MASTER_DEBT_PIR_DATA.pir_national, title: '주요국 소득 대비 주택가격비율(PIR) 전국 비교 (OECD 기준)', unit: '배' };
  if (currentDebtPirSubType === 'pir_cities') {
    // For cities, map keys
    const cityData = {};
    Object.keys(MASTER_DEBT_PIR_DATA.pir_cities).forEach(k => {
      cityData[k] = MASTER_DEBT_PIR_DATA.pir_cities[k].data;
    });
    return { data: cityData, title: '서울 vs 뉴욕·런던·도쿄·베이징·시드니 대도시 PIR 비교', unit: '배', isCity: true };
  }
  if (currentDebtPirSubType === 'buffett') return { data: MASTER_DEBT_PIR_DATA.buffett, title: '글로벌 주요국 버핏 지수 (GDP 대비 상장주식 시가총액 비율)', unit: '%' };
  if (currentDebtPirSubType === 'ext_st') return { data: { 'KR': MASTER_DEBT_PIR_DATA.ext.KR_ST_DEBT }, title: '대한민국 외환보유액 대비 단기외채 비율 (외환위기 조기경보)', unit: '%' };
  if (currentDebtPirSubType === 'ext_ca') return { data: { 'KR': MASTER_DEBT_PIR_DATA.ext.KR_CurrentAccount_GDP, 'US': MASTER_DEBT_PIR_DATA.ext.US_CA, 'DE': MASTER_DEBT_PIR_DATA.ext.DE_CA, 'JP': MASTER_DEBT_PIR_DATA.ext.JP_CA }, title: '주요국 경상수지 / GDP 비율 추이', unit: '%' };
  return { data: MASTER_DEBT_PIR_DATA.debt_hh, title: '주요국 GDP 대비 가계부채비율', unit: '%' };
}

function renderDebtPirChart() {
  const container = document.getElementById('svgDebtPirContainer');
  if (!container) return;

  const datasetInfo = getActiveDebtDataset();
  document.getElementById('debtPirChartTitle').textContent = datasetInfo.title + ' (1995~2026)';

  let years = [...MASTER_DEBT_PIR_DATA.years];
  if (currentDebtPirRange === '20y') years = years.filter(y => y >= 2006);
  else if (currentDebtPirRange === '10y') years = years.filter(y => y >= 2016);
  else if (currentDebtPirRange === '5y') years = years.filter(y => y >= 2021);

  // Update Legend
  const legendBox = document.getElementById('debtPirChartLegend');
  if (legendBox) {
    legendBox.innerHTML = '';
    const activeEntities = datasetInfo.isCity ? Object.keys(MASTER_DEBT_PIR_DATA.pir_cities) : currentDebtSelectedCountries;
    activeEntities.forEach(code => {
      let name = code;
      let col = '#38bdf8';
      let flag = '';
      if (datasetInfo.isCity) {
        const item = MASTER_DEBT_PIR_DATA.pir_cities[code];
        if (item) { name = item.name; col = item.color; flag = item.flag; }
      } else {
        const item = MASTER_DEBT_PIR_DATA.countries[code];
        if (item) { name = item.name; col = item.color; flag = item.flag; }
      }
      const legItem = document.createElement('div');
      legItem.style.cssText = 'display:flex; align-items:center; gap:6px; font-size:12px; color:#cbd5e1;';
      legItem.innerHTML = `<span style="display:inline-block; width:14px; height:3px; background:${col}; border-radius:2px;"></span> <span>${flag} ${name}</span>`;
      legendBox.appendChild(legItem);
    });
  }

  // Calculate Min and Max values for Y axis
  let minVal = 999999;
  let maxVal = -999999;
  const activeEntities = datasetInfo.isCity ? Object.keys(MASTER_DEBT_PIR_DATA.pir_cities) : currentDebtSelectedCountries;

  activeEntities.forEach(code => {
    const series = datasetInfo.data[code];
    if (series) {
      years.forEach(y => {
        const v = series[y];
        if (v !== undefined) {
          if (v < minVal) minVal = v;
          if (v > maxVal) maxVal = v;
        }
      });
    }
  });

  if (minVal === 999999) { minVal = 0; maxVal = 100; }
  minVal = Math.max(0, Math.floor(minVal * 0.85));
  maxVal = Math.ceil(maxVal * 1.12);
  if (maxVal <= minVal) maxVal = minVal + 10;

  // Update KPI Cards based on KR data
  updateDebtPirKPIs(datasetInfo);

  // Build SVG
  const width = container.clientWidth || 960;
  const height = 380;
  const padLeft = 60;
  const padRight = 30;
  const padTop = 30;
  const padBottom = 40;
  const chartW = width - padLeft - padRight;
  const chartH = height - padTop - padBottom;

  const getX = (idx) => padLeft + (idx / (years.length - 1)) * chartW;
  const getY = (val) => padTop + chartH - ((val - minVal) / (maxVal - minVal)) * chartH;

  let svgHtml = `<svg width="100%" height="100%" viewBox="0 0 ${width} ${height}" style="overflow: visible;" xmlns="http://www.w3.org/2000/svg">`;

  // Grid lines
  const gridSteps = 5;
  for (let i = 0; i <= gridSteps; i++) {
    const gVal = minVal + ((maxVal - minVal) / gridSteps) * i;
    const yPos = getY(gVal);
    svgHtml += `<line x1="${padLeft}" y1="${yPos}" x2="${padLeft + chartW}" y2="${yPos}" stroke="rgba(255,255,255,0.08)" stroke-dasharray="3,3"/>`;
    svgHtml += `<text x="${padLeft - 10}" y="${yPos + 4}" fill="#64748b" font-size="11" text-anchor="end" font-family="monospace">${gVal.toFixed(1)}${datasetInfo.unit}</text>`;
  }

  // X Axis labels
  const xStep = Math.max(1, Math.floor(years.length / 7));
  years.forEach((y, idx) => {
    if (idx % xStep === 0 || idx === years.length - 1) {
      const xPos = getX(idx);
      svgHtml += `<text x="${xPos}" y="${height - 12}" fill="#94a3b8" font-size="11" text-anchor="middle" font-family="monospace">${y}</text>`;
    }
  });

  // Render lines for each entity
  activeEntities.forEach(code => {
    const series = datasetInfo.data[code];
    if (!series) return;

    let points = [];
    years.forEach((y, idx) => {
      const val = series[y];
      if (val !== undefined) {
        points.push({ x: getX(idx), y: getY(val), val, year: y });
      }
    });

    if (points.length === 0) return;

    let col = '#38bdf8';
    let isDash = false;
    let strokeW = 2.4;

    if (datasetInfo.isCity) {
      const item = MASTER_DEBT_PIR_DATA.pir_cities[code];
      if (item) { col = item.color; if (code.includes('SEOUL')) strokeW = 3.6; }
    } else {
      const item = MASTER_DEBT_PIR_DATA.countries[code];
      if (item) {
        col = item.color;
        if (code === 'KR') strokeW = 3.6;
        if (item.dash) isDash = true;
      }
    }

    const pathData = points.reduce((acc, p, idx) => acc + (idx === 0 ? `M ${p.x} ${p.y}` : ` L ${p.x} ${p.y}`), '');
    const dashAttr = isDash ? 'stroke-dasharray="4,4"' : '';
    svgHtml += `<path d="${pathData}" fill="none" stroke="${col}" stroke-width="${strokeW}" ${dashAttr} stroke-linejoin="round" stroke-linecap="round"/>`;

    // Points
    points.forEach(p => {
      svgHtml += `<circle cx="${p.x}" cy="${p.y}" r="${p.year === 2026 ? 5 : 3}" fill="${col}" stroke="#0b0f19" stroke-width="1.5" style="transition: transform 0.2s; cursor: pointer;"/>`;
    });
  });

  svgHtml += `</svg>`;

  // Create Tooltip overlay
  svgHtml += `
    <div id="debtPirTooltip" style="position: absolute; display: none; background: rgba(15, 23, 42, 0.95); border: 1px solid rgba(56, 189, 248, 0.4); border-radius: 10px; padding: 12px 16px; font-size: 12px; color: #fff; pointer-events: none; z-index: 100; box-shadow: 0 10px 25px rgba(0,0,0,0.6); max-width: 320px; backdrop-filter: blur(10px);">
    </div>
  `;

  container.innerHTML = svgHtml;

  // Add Hover Interaction to Container
  container.onmousemove = function(e) {
    const rect = container.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    if (mouseX < padLeft || mouseX > padLeft + chartW) {
      const tt = document.getElementById('debtPirTooltip');
      if (tt) tt.style.display = 'none';
      return;
    }

    const relX = mouseX - padLeft;
    const idx = Math.min(years.length - 1, Math.max(0, Math.round((relX / chartW) * (years.length - 1))));
    const targetYear = years[idx];

    const tooltip = document.getElementById('debtPirTooltip');
    if (!tooltip) return;

    let ttContent = `<div style="font-weight: 800; color: #38bdf8; font-size: 13px; margin-bottom: 6px; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 4px;">📅 ${targetYear}년 확정 통계</div>`;
    
    activeEntities.forEach(code => {
      let name = code;
      let col = '#38bdf8';
      let flag = '';
      if (datasetInfo.isCity) {
        const item = MASTER_DEBT_PIR_DATA.pir_cities[code];
        if (item) { name = item.name; col = item.color; flag = item.flag; }
      } else {
        const item = MASTER_DEBT_PIR_DATA.countries[code];
        if (item) { name = item.name; col = item.color; flag = item.flag; }
      }
      const val = datasetInfo.data[code] ? datasetInfo.data[code][targetYear] : '-';
      ttContent += `<div style="display:flex; justify-content:space-between; gap:12px; margin-bottom:3px;"><span style="color:${col}; font-weight:700;">${flag} ${name}:</span> <span style="font-weight:800; font-family:monospace;">${val}${datasetInfo.unit}</span></div>`;
    });

    const evt = MASTER_DEBT_PIR_DATA.events[targetYear];
    if (evt) {
      ttContent += `<div style="margin-top: 6px; padding-top: 6px; border-top: 1px dashed rgba(255,255,255,0.15); font-size: 11px; color: #fbbf24; line-height: 1.4;">🏛️ <strong>역사적 변곡점:</strong> ${evt}</div>`;
    }

    tooltip.innerHTML = ttContent;
    tooltip.style.display = 'block';

    let leftPos = mouseX + 15;
    if (leftPos + 280 > width) leftPos = mouseX - 290;
    tooltip.style.left = leftPos + 'px';
    tooltip.style.top = '40px';
  };

  container.onmouseleave = function() {
    const tt = document.getElementById('debtPirTooltip');
    if (tt) tt.style.display = 'none';
  };
}

function updateDebtPirKPIs(datasetInfo) {
  const krData = datasetInfo.data['KR'] || (datasetInfo.isCity ? datasetInfo.data['KR_SEOUL'] : null);
  const usData = datasetInfo.data['US'] || (datasetInfo.isCity ? datasetInfo.data['US_NYC'] : null);
  const oecdData = datasetInfo.data['OECD'] || null;

  if (krData) {
    const curVal = krData[2026] !== undefined ? krData[2026] : '-';
    const prevVal = krData[2025] !== undefined ? krData[2025] : curVal;
    const diff = (curVal - prevVal).toFixed(1);
    const sign = diff >= 0 ? '+' : '';

    const elKrVal = document.getElementById('kpiDebtKrVal');
    if (elKrVal) elKrVal.textContent = curVal + datasetInfo.unit;

    const elKrSub = document.getElementById('kpiDebtKrSub');
    if (elKrSub) elKrSub.textContent = `2026.10 KST 확정치 (YoY ${sign}${diff}${datasetInfo.unit})`;

    // ATH
    let maxVal = -999;
    let maxYear = 1995;
    Object.keys(krData).forEach(y => {
      if (krData[y] > maxVal) { maxVal = krData[y]; maxYear = y; }
    });
    const elAthVal = document.getElementById('kpiDebtAthVal');
    if (elAthVal) elAthVal.textContent = maxVal + datasetInfo.unit;
    const elAthSub = document.getElementById('kpiDebtAthSub');
    if (elAthSub) elAthSub.textContent = `${maxYear}년 사상 최고치 기록`;
  }

  if (usData && krData) {
    const usVal = usData[2026] !== undefined ? usData[2026] : '-';
    const krVal = krData[2026] !== undefined ? krData[2026] : 0;
    const gap = (krVal - usVal).toFixed(1);
    const elUsVal = document.getElementById('kpiDebtUsVal');
    if (elUsVal) elUsVal.textContent = usVal + datasetInfo.unit;
    const elUsSub = document.getElementById('kpiDebtUsSub');
    if (elUsSub) elUsSub.textContent = `한국과의 스프레드: ${gap > 0 ? '+' : ''}${gap}${datasetInfo.unit}`;
  }

  if (oecdData) {
    const oecdVal = oecdData[2026] !== undefined ? oecdData[2026] : '-';
    const elOecdVal = document.getElementById('kpiDebtOecdVal');
    if (elOecdVal) elOecdVal.textContent = oecdVal + datasetInfo.unit;
  }

  // Status traffic light
  const elStatusVal = document.getElementById('kpiDebtStatusVal');
  const elStatusSub = document.getElementById('kpiDebtStatusSub');
  if (elStatusVal && elStatusSub) {
    if (currentDebtPirSubType === 'debt_hh') {
      elStatusVal.textContent = '주의 (Yellow)';
      elStatusVal.style.color = '#fbbf24';
      elStatusSub.textContent = 'BIS 위험 임계치(80%) 상회하나 92.8%로 디레버리징 중';
    } else if (currentDebtPirSubType === 'debt_gov') {
      elStatusVal.textContent = '양호 (Green)';
      elStatusVal.style.color = '#34d399';
      elStatusSub.textContent = 'D2 53.8%로 OECD 평균(112.4%) 대비 건전성 유지';
    } else if (currentDebtPirSubType === 'pir_national' || currentDebtPirSubType === 'pir_cities') {
      elStatusVal.textContent = '경계 (Orange)';
      elStatusVal.style.color = '#f97316';
      elStatusSub.textContent = '서울 아파트 PIR 13.8배 고평가, 글로벌 대도시 상회';
    } else if (currentDebtPirSubType === 'ext_st') {
      elStatusVal.textContent = '안전 (Green)';
      elStatusVal.style.color = '#34d399';
      elStatusSub.textContent = '단기외채비율 30.8%로 1997년(286%) 대비 철벽 방어';
    } else {
      elStatusVal.textContent = '정상 (Green)';
      elStatusVal.style.color = '#34d399';
      elStatusSub.textContent = '글로벌 거시 지표 벤치마크 범위 내 안착';
    }
  }
}

function renderDebtPirTable() {
  const datasetInfo = getActiveDebtDataset();
  const thead = document.getElementById('debtPirTableHead');
  const tbody = document.getElementById('debtPirTableBody');
  if (!thead || !tbody) return;

  const activeEntities = datasetInfo.isCity ? Object.keys(MASTER_DEBT_PIR_DATA.pir_cities) : currentDebtSelectedCountries;

  // Render Table Header
  let thHtml = `<tr><th style="width: 10%;">연도</th>`;
  activeEntities.forEach(code => {
    let name = code;
    let flag = '';
    if (datasetInfo.isCity) {
      const item = MASTER_DEBT_PIR_DATA.pir_cities[code];
      if (item) { name = item.name; flag = item.flag; }
    } else {
      const item = MASTER_DEBT_PIR_DATA.countries[code];
      if (item) { name = item.name; flag = item.flag; }
    }
    thHtml += `<th style="text-align: right;">${flag} ${name}</th>`;
  });
  thHtml += `<th style="width: 35%;">해당 연도 주요 거시경제 정책 및 시장 충격 이벤트</th></tr>`;
  thead.innerHTML = thHtml;

  // Render Table Body (descending years)
  let years = [...MASTER_DEBT_PIR_DATA.years].reverse();
  if (currentDebtPirRange === '20y') years = years.filter(y => y >= 2006);
  else if (currentDebtPirRange === '10y') years = years.filter(y => y >= 2016);
  else if (currentDebtPirRange === '5y') years = years.filter(y => y >= 2021);

  let tbHtml = '';
  years.forEach(y => {
    const evt = MASTER_DEBT_PIR_DATA.events[y] || '-';
    tbHtml += `<tr>`;
    tbHtml += `<td style="font-family: monospace; font-weight: 700; color: #38bdf8;">${y}년</td>`;

    activeEntities.forEach(code => {
      const series = datasetInfo.data[code];
      const val = series && series[y] !== undefined ? series[y] : '-';
      const prevVal = series && series[y - 1] !== undefined ? series[y - 1] : val;
      let chgBadge = '';
      if (val !== '-' && prevVal !== '-' && y > 1995) {
        const diff = (val - prevVal).toFixed(1);
        if (diff > 0) chgBadge = `<span style="font-size:10px; color:#f87171; margin-left:4px;">▲${diff}</span>`;
        else if (diff < 0) chgBadge = `<span style="font-size:10px; color:#34d399; margin-left:4px;">▼${Math.abs(diff)}</span>`;
      }
      tbHtml += `<td style="text-align: right; font-family: monospace; font-weight: 700;">${val}${datasetInfo.unit} ${chgBadge}</td>`;
    });

    tbHtml += `<td style="font-size: 12px; color: #cbd5e1; line-height: 1.4;">${evt}</td>`;
    tbHtml += `</tr>`;
  });

  tbody.innerHTML = tbHtml;
}

function downloadDebtPirCSV() {
  const datasetInfo = getActiveDebtDataset();
  const activeEntities = datasetInfo.isCity ? Object.keys(MASTER_DEBT_PIR_DATA.pir_cities) : currentDebtSelectedCountries;

  let csv = '﻿'; // UTF-8 BOM
  csv += `연도,`;
  activeEntities.forEach(code => {
    let name = code;
    if (datasetInfo.isCity) {
      const item = MASTER_DEBT_PIR_DATA.pir_cities[code];
      if (item) name = item.name.replace(/,/g, '');
    } else {
      const item = MASTER_DEBT_PIR_DATA.countries[code];
      if (item) name = item.name.replace(/,/g, '');
    }
    csv += `${name}(${datasetInfo.unit}),`;
  });
  csv += `주요 정책 및 거시경제 이벤트\n`;

  let years = [...MASTER_DEBT_PIR_DATA.years].reverse();
  years.forEach(y => {
    csv += `${y},`;
    activeEntities.forEach(code => {
      const series = datasetInfo.data[code];
      const val = series && series[y] !== undefined ? series[y] : '';
      csv += `${val},`;
    });
    const evt = (MASTER_DEBT_PIR_DATA.events[y] || '').replace(/,/g, ' ');
    csv += `"${evt}"\n`;
  });

  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${datasetInfo.title.replace(/[^a-zA-Z0-9가-힣]/g, '_')}_1995_2026.csv`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function renderGlobalDebtPirLab() {
  setDebtPirCategory('debt');
}

