let currentTtFilter = 'all';
let currentTtSpotlightIndex = 0;
let ttSpotlightTimer = null;

function filterThinkTankLiveFeed(cat) {
  currentTtFilter = cat;
  document.querySelectorAll('.tt-filter-btn').forEach(b => b.classList.remove('active'));
  const btn = document.getElementById('btnTtFilter_' + cat);
  if (btn) btn.classList.add('active');

  renderThinkTankFeedGrid();
}

function renderThinkTankFeedGrid() {
  const grid = document.getElementById('thinktankFeedGrid');
  if (!grid) return;
  grid.innerHTML = '';

  const filtered = THINKTANK_EMAIL_FEED_DATA.filter(item => {
    if (currentTtFilter === 'all') return true;
    return item.origin === currentTtFilter;
  });

  filtered.forEach((item, idx) => {
    const card = document.createElement('div');
    card.className = 'tt-feed-card';
    const originBadge = item.origin === 'overseas' ? 
      '<span style="background:rgba(56,189,248,0.15); border:1px solid rgba(56,189,248,0.4); color:#38bdf8; font-size:10.5px; font-weight:800; padding:2px 7px; border-radius:4px;">🌐 글로벌</span>' :
      '<span style="background:rgba(52,211,153,0.15); border:1px solid rgba(52,211,153,0.4); color:#34d399; font-size:10.5px; font-weight:800; padding:2px 7px; border-radius:4px;">🇰🇷 국내국책</span>';

    card.innerHTML = `
      <div>
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px;">
          <div style="display:flex; align-items:center; gap:6px;">
            ${originBadge}
            <span style="font-size:11px; color:#94a3b8;">${item.received_at}</span>
          </div>
          <span style="background:rgba(255,255,255,0.06); font-size:10.5px; font-weight:700; color:#a1a1aa; padding:2px 6px; border-radius:4px;">${item.tag}</span>
        </div>
        <div style="font-size:0.85rem; font-weight:800; color:#38bdf8; margin-bottom:4px;">${item.org}</div>
        <h4 style="font-size:0.98rem; font-weight:800; color:#fff; line-height:1.45; margin:0 0 10px 0;">${item.title}</h4>
        <p style="font-size:0.82rem; color:#cbd5e1; line-height:1.5; margin:0 0 14px 0;">
          ${item.summary[0]}
        </p>
      </div>
      <div style="display:flex; justify-content:space-between; align-items:center; border-top:1px solid rgba(255,255,255,0.08); padding-top:10px;">
        <span style="font-size:11px; color:#34d399; font-weight:700;">● 3분 핵심 요약본 완비</span>
        <button onclick="openThinkTankModalById('${item.id}')" style="background:none; border:none; color:#38bdf8; font-size:12px; font-weight:700; cursor:pointer;">
          열람 &gt;
        </button>
      </div>
    `;
    grid.appendChild(card);
  });
}

function updateThinkTankSpotlight() {
  const item = THINKTANK_EMAIL_FEED_DATA[currentTtSpotlightIndex];
  if (!item) return;

  const badge = document.getElementById('ttSpotlightBadge');
  if (badge) {
    badge.textContent = item.origin === 'overseas' ? '🌐 글로벌 싱크탱크 속보' : '🇰🇷 국내 국책 싱크탱크 속보';
    badge.style.background = item.origin === 'overseas' ? '#0284c7' : '#059669';
  }

  const elOrg = document.getElementById('ttSpotlightOrg');
  if (elOrg) elOrg.textContent = item.org + ' (' + item.country + ')';

  const elTime = document.getElementById('ttSpotlightTime');
  if (elTime) elTime.textContent = item.received_at;

  const elTitle = document.getElementById('ttSpotlightTitle');
  if (elTitle) elTitle.textContent = item.title;

  const elSummary = document.getElementById('ttSpotlightSummary');
  if (elSummary) {
    elSummary.innerHTML = item.summary.map(s => `<div>• ${s}</div>`).join('');
  }

  const elImp = document.getElementById('ttSpotlightImplication');
  if (elImp) elImp.textContent = item.implication;

  const btnDetail = document.getElementById('ttSpotlightDetailBtn');
  if (btnDetail) {
    btnDetail.onclick = () => openThinkTankModalById(item.id);
  }
}

function nextThinkTankSpotlight() {
  currentTtSpotlightIndex = (currentTtSpotlightIndex + 1) % THINKTANK_EMAIL_FEED_DATA.length;
  updateThinkTankSpotlight();
}

function prevThinkTankSpotlight() {
  currentTtSpotlightIndex = (currentTtSpotlightIndex - 1 + THINKTANK_EMAIL_FEED_DATA.length) % THINKTANK_EMAIL_FEED_DATA.length;
  updateThinkTankSpotlight();
}

function openThinkTankModalById(id) {
  const item = THINKTANK_EMAIL_FEED_DATA.find(t => t.id === id);
  if (!item) return;

  document.getElementById('modalTtOrgBadge').textContent = item.country;
  document.getElementById('modalTtTime').textContent = item.received_at;
  document.getElementById('modalTtTitle').textContent = item.title;
  document.getElementById('modalTtOrg').textContent = item.org + ' · ' + item.tag;

  const bulletList = document.getElementById('modalTtBullets');
  bulletList.innerHTML = item.summary.map(s => `<li style="margin-bottom:6px;">${s}</li>`).join('');

  document.getElementById('modalTtImplication').textContent = item.implication;
  
  const link = document.getElementById('modalTtLink');
  link.href = item.url;

  const modal = document.getElementById('thinktankReportModal');
  modal.style.display = 'flex';
}

function closeThinkTankModal() {
  const modal = document.getElementById('thinktankReportModal');
  if (modal) modal.style.display = 'none';
}

function initThinkTankEmailRadar() {
  renderThinkTankFeedGrid();
  updateThinkTankSpotlight();
  if (ttSpotlightTimer) clearInterval(ttSpotlightTimer);
  ttSpotlightTimer = setInterval(nextThinkTankSpotlight, 12000); // 12 seconds auto rotation
}

// Auto-initialize Global Debt/PIR Lab and Think Tank Email Radar
document.addEventListener('DOMContentLoaded', function() {
  renderGlobalDebtPirLab();
  initThinkTankEmailRadar();
  renderMusicTracksStrip();
});
if (document.readyState === 'complete' || document.readyState === 'interactive') {
  setTimeout(() => {
    renderGlobalDebtPirLab();
    initThinkTankEmailRadar();
  renderMusicTracksStrip();
  }, 50);
}


