let currentMusicIdx = 0;
let musicHighlightTimer = null;
let musicCountdownInterval = null;
let isMusicHighlightMode = false;

function renderMusicTracksStrip() {
  const strip = document.getElementById('musicTracksStrip');
  if (!strip) return;
  strip.innerHTML = YOUTUBE_MUSIC_TRACKS.map((tr, i) => `
    <button class="music-track-chip ${i === currentMusicIdx && isMusicHighlightMode ? 'active' : ''}" onclick="playMusicTrackHighlight(${i})">
      <span>🎵</span>
      <span>${tr.title.length > 22 ? tr.title.slice(0, 22) + '...' : tr.title}</span>
      <span style="font-size: 9.5px; opacity: 0.75; background: rgba(255,255,255,0.15); padding: 1px 5px; border-radius: 4px;">10초</span>
    </button>
  `).join('');
}

function formatSecToMin(sec) {
  const m = Math.floor(sec / 60);
  const s = sec % 60;
  return `${m < 10 ? '0' + m : m}:${s < 10 ? '0' + s : s}`;
}

function playMusicTrackHighlight(idx, scroll = false) {
  isMusicHighlightMode = true;
  currentMusicIdx = idx;
  const track = YOUTUBE_MUSIC_TRACKS[idx];
  const iframe = document.getElementById('hubVideoIframe');
  const badge = document.getElementById('music10sBadge');
  const nameEl = document.getElementById('musicTrackName');
  const timeEl = document.getElementById('musicTimeWindow');
  const countEl = document.getElementById('musicCountdownSec');
  const fillEl = document.getElementById('musicProgressLineFill');
  const headEl = document.getElementById('hubHeadline');
  const sumEl = document.getElementById('hubSummary');
  const subEl = document.getElementById('hubSubtitleText');

  if (!iframe || !track) return;

  const startSec = track.highlightStart;
  const endSec = startSec + track.duration;

  // Set YouTube embed to exact middle highlight 10 seconds
  iframe.src = `https://www.youtube.com/embed/${track.id}?start=${startSec}&end=${endSec}&autoplay=1&playsinline=1&rel=0&modestbranding=1&enablejsapi=1`;

  // Update HUD badge
  if (badge) badge.style.display = 'block';
  if (nameEl) nameEl.textContent = `🎵 [10초 하이라이트] ${track.title}`;
  if (timeEl) timeEl.textContent = `중간 하이라이트 (${formatSecToMin(startSec)} ~ ${formatSecToMin(endSec)}) 재생 중 · 10초 후 자동 다음 곡`;

  if (headEl) headEl.textContent = `🎵 [10초 음악 하이라이트] ${track.title}`;
  if (sumEl) sumEl.textContent = `${track.artist} · ${track.tag} · 중간 10초 핵심 하이라이트 구간 연속 재생 모드`;
  if (subEl) subEl.textContent = `🎵 10초 하이라이트 감상 중: ${formatSecToMin(startSec)} ~ ${formatSecToMin(endSec)} 구간 | 다음 명곡으로 10초마다 자동 순환됩니다.`;

  renderMusicTracksStrip();

  // 10s countdown animation
  let remain = 10;
  if (countEl) countEl.textContent = remain;
  if (fillEl) {
    fillEl.style.transition = 'none';
    fillEl.style.transform = 'scaleX(1)';
    setTimeout(() => {
      fillEl.style.transition = 'transform 10s linear';
      fillEl.style.transform = 'scaleX(0)';
    }, 50);
  }

  if (musicCountdownInterval) clearInterval(musicCountdownInterval);
  musicCountdownInterval = setInterval(() => {
    remain -= 1;
    if (remain >= 0 && countEl) {
      countEl.textContent = remain;
    }
    if (remain <= 0) {
      clearInterval(musicCountdownInterval);
    }
  }, 1000);

  if (musicHighlightTimer) clearTimeout(musicHighlightTimer);
  // After 10.5 seconds, auto-advance to next music track
  musicHighlightTimer = setTimeout(() => {
    if (isMusicHighlightMode) {
      const nextIdx = (currentMusicIdx + 1) % YOUTUBE_MUSIC_TRACKS.length;
      playMusicTrackHighlight(nextIdx, false);
    }
  }, 10500);

  if (scroll) {
    const container = document.getElementById('hubVideoContainer');
    if (container) container.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }
}

function startMusic10sHighlights(btn) {
  isMusicHighlightMode = true;
  document.querySelectorAll('.pill-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  playMusicTrackHighlight(0, true);
}


/* ==========================================================================
   🎬 CINEMA & 🎧 MUSIC LAB JAVASCRIPT CONTROLLERS
   ========================================================================== */

function switchMcTab(tabId, btn) {
  document.querySelectorAll('.mc-pane').forEach(p => p.classList.remove('active'));
  document.querySelectorAll('.mc-tab-btn').forEach(b => b.classList.remove('active'));
  
  const pane = document.getElementById(tabId);
  if (pane) pane.classList.add('active');
  if (btn) btn.classList.add('active');
}

function playCustomVideo(videoId, title) {
  const iframe = document.getElementById('hubVideoIframe');
  const headEl = document.getElementById('hubHeadline');
  const sumEl = document.getElementById('hubSummary');
  const subEl = document.getElementById('hubSubtitleText');
  const container = document.getElementById('hubVideoContainer');
  const badge = document.getElementById('music10sBadge');

  if (badge) badge.style.display = 'none';

  if (iframe) {
    iframe.src = `https://www.youtube.com/embed/${videoId}?autoplay=1&playsinline=1&rel=0&modestbranding=1&enablejsapi=1`;
  }
  if (headEl) headEl.textContent = `🎬 [시네마 & 음악 명장면] ${title}`;
  if (sumEl) sumEl.textContent = `영선 님의 연구소 🔠Contents 아카이브 연계 영상: ${title} 실시간 스트리밍 중`;
  if (subEl) subEl.textContent = `🎬 문화 예술 아카이브: ${title} | 스크린과 선율이 머무는 지식 인텔리전스`;

  if (container) {
    container.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }
}
